using AdDatabase.BLL.Models;using System.Net;using System.Text.Json;
namespace AdDatabase.API.Middleware;public class ExceptionMiddleware(RequestDelegate next,ILogger<ExceptionMiddleware> log){public async Task InvokeAsync(HttpContext c){try{await next(c);}catch(Exception e){log.LogError(e,"Unhandled request error {TraceId}",c.TraceIdentifier);c.Response.ContentType="application/json";c.Response.StatusCode=e switch{KeyNotFoundException=>(int)HttpStatusCode.NotFound,UnauthorizedAccessException=>(int)HttpStatusCode.Unauthorized,InvalidOperationException=>(int)HttpStatusCode.BadRequest,_=>(int)HttpStatusCode.InternalServerError};var message=c.Response.StatusCode==500?"An unexpected error occurred":e.Message;await c.Response.WriteAsync(JsonSerializer.Serialize(ApiResponse<object>.Fail(message)));}}}
